62	      fprintf(stderr, "Failed to open \"%s\", aborting.\n", path);
63	      exit(EXIT_FAILURE);
64	   }
65	
66	   col = mongoc_client_get_collection(client, database, collection);
67	   cursor = mongoc_collection_find_with_opts(col, &query, NULL, NULL);
